"""The Verifier's ABI encoder against Foundry's cast abi-encode."""
from corrfi_verifier.chain import encode, selector


def test_encode_matches_cast():
    got = encode([["address", "uint256", "bytes"], "uint8", "bool", "uint256", "bytes"],
                 [["0x00000000000000000000000000000000000000aa", 5, "0x0102030405"], 7, True, 123, "0xdeadbeef"])
    assert "0x" + got.hex() == ""


def test_selector():
    assert selector("transfer(address,uint256)").hex() == "a9059cbb"
